namespace graph {
    class Graph {
    public:
        Graph(int numNodes) : numNodes(numNodes), adj(numNodes) {}

        void addEdge(int u, int v) {
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        bool hasEdge(int u, int v) {
            return std::find(adj[u].begin(), adj[u].end(), v) != adj[u].end();
        }

        int shortestPath(int start, int end) {
            if (start == end) return 0;

            std::vector<int> dist(numNodes, std::numeric_limits<int>::max());
            std::priority_queue<std::pair<int, int>, std::vector<std::pair<int, int>>, std::greater<std::pair<int, int>>> pq;

            dist[start] = 0;
            pq.push({0, start});

            while (!pq.empty()) {
                int currentDist = pq.top().first;
                int currentNode = pq.top().second;
                pq.pop();

                if (currentNode == end) break;

                if (currentDist > dist[currentNode]) continue;

                for (int neighbor : adj[currentNode]) {
                    if (dist[neighbor] > dist[currentNode] + 1) {
                        dist[neighbor] = dist[currentNode] + 1;
                        pq.push({dist[neighbor], neighbor});
                    }
                }
            }

            return dist[end];
        }

    private:
        int numNodes;
        std::vector<std::vector<int>> adj;
    };
